import time
import functools

def retry_with_backoff(func=None, *, retries=3, initial_delay=0.1, backoff_factor=2):
    """Retry a function with exponential backoff.

    Can be used as a decorator ``@retry_with_backoff`` or called directly
    ``retry_with_backoff(my_func)(*args, **kwargs)``.

    Args:
        func: The function to wrap. If ``None`` the returned value is a decorator.
        retries: Number of retry attempts after the initial call.
        initial_delay: Delay before the first retry (seconds).
        backoff_factor: Multiplier applied to the delay after each retry.
    """
    def decorator(f):
        @functools.wraps(f)
        def wrapper(*args, **kwargs):
            delay = initial_delay
            attempt = 0
            while True:
                try:
                    return f(*args, **kwargs)
                except Exception:
                    if attempt >= retries:
                        raise
                    time.sleep(delay)
                    delay *= backoff_factor
                    attempt += 1
        return wrapper
    if func is None:
        return decorator
    else:
        return decorator(func)

