def retry_with_backoff(fn=None, *, max_retries=3, initial_delay=0.1, backoff_factor=2):
    """Simple retry decorator with exponential backoff.

    Usage as a decorator::

        @retry_with_backoff(max_retries=5, initial_delay=0.2)
        def fragile():
            ...

    It will retry the wrapped function up to ``max_retries`` times, waiting
    ``initial_delay`` seconds before the first retry and multiplying the
    delay by ``backoff_factor`` after each subsequent failure.

    The decorator also works as a plain function wrapper:
    ``retry_with_backoff(some_callable)(*args, **kwargs)``.
    """

    def decorator(func):
        import time
        import functools

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            delay = initial_delay
            for attempt in range(max_retries + 1):
                try:
                    return func(*args, **kwargs)
                except Exception:
                    if attempt == max_retries:
                        raise
                    time.sleep(delay)
                    delay *= backoff_factor
        return wrapper

    # If used without parentheses e.g. @retry_with_backoff
    if fn is not None and callable(fn):
        return decorator(fn)
    return decorator

